/**
 * Cover art for a deck, made from the deck's own name: the same engraved
 * look as the card backs and the vice, barrier, culture and insight art (a deep
 * field, fine metallic line work, crop marks) with a rosette that is different
 * for every deck. Nothing is fetched or generated by a model, so it is free,
 * instant and always the same for the same deck.
 */

/** FNV-1a: a small, stable string hash. */
export function hashSeed(text: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/** A tiny seeded generator, so one hash yields every parameter in a fixed order. */
function stream(seed: number): () => number {
  let s = seed || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5; s >>>= 0;
    return s / 0xffffffff;
  };
}

/** The four hues of the card art: vice bronze, barrier sage, culture green, insight teal. */
export const COVER_PALETTES = [
  { name: 'bronze', accent: '#71594b', metal: ['#f0e1b6', '#b9a173', '#7c6a4e'], field: ['#3b2f27', '#241b17', '#120e0c'] },
  { name: 'sage', accent: '#5f6958', metal: ['#e8ecc9', '#b3bb8e', '#6e7a57'], field: ['#34402f', '#202a1d', '#0f150d'] },
  { name: 'green', accent: '#4e715b', metal: ['#f0e1b6', '#baad7c', '#787d58'], field: ['#31584c', '#17392f', '#0b1d19'] },
  { name: 'teal', accent: '#526e68', metal: ['#dcefe8', '#9fc4bb', '#5f8c82'], field: ['#2c5651', '#173a37', '#0a1c1b'] },
] as const;

export interface CoverSpec {
  palette: (typeof COVER_PALETTES)[number];
  /** Rosette: outer and inner circle of the rolling curve, and the pen offset. */
  outer: number;
  inner: number;
  pen: number;
  /** How many rotated copies make the rosette. */
  copies: number;
  /** Concentric guide rings, as radii (0..1 of the rosette). */
  rings: number[];
  /** Quarter turns and fine rotation of the whole rosette, degrees. */
  rotation: number;
  /** The deck's small ordinal mark, "No. 07" style, 1..99. */
  ordinal: number;
}

export function coverSpec(seedText: string): CoverSpec {
  const rand = stream(hashSeed(seedText.trim().toLowerCase() || 'deck'));
  const palette = COVER_PALETTES[Math.floor(rand() * COVER_PALETTES.length)]!;
  // Rolling-circle (hypotrochoid) ratios that close into clean rosettes with 5 to 9 lobes.
  const lobes = 5 + Math.floor(rand() * 5);
  const outer = lobes * 12;
  const inner = outer - 12 * (1 + Math.floor(rand() * 2));
  const pen = 20 + Math.floor(rand() * 26);
  const copies = 6 + Math.floor(rand() * 4);
  const ringCount = 3 + Math.floor(rand() * 3);
  const rings = Array.from({ length: ringCount }, (_, i) => 0.42 + (i + 1) * (0.5 / (ringCount + 1)));
  return {
    palette,
    outer,
    inner,
    pen,
    copies,
    rings,
    rotation: Math.floor(rand() * 360),
    ordinal: 1 + Math.floor(rand() * 99),
  };
}

function gcd(a: number, b: number): number {
  return b === 0 ? a : gcd(b, a % b);
}

/** One closed rosette curve, scaled to fit radius `radius` around (cx, cy). */
function rosettePath(spec: CoverSpec, cx: number, cy: number, radius: number, turn: number): string {
  const R = spec.outer;
  const r = Math.max(1, spec.inner);
  const d = spec.pen;
  const revolutions = r / gcd(R, r);
  const extent = Math.abs(R - r) + d;
  const scale = radius / extent;
  // Enough points to read as a smooth line at card size, few enough that a library of decks stays light.
  const steps = Math.min(260, 50 * revolutions);
  const cos = Math.cos(turn);
  const sin = Math.sin(turn);
  let path = '';
  for (let i = 0; i <= steps; i += 1) {
    const t = (i / steps) * Math.PI * 2 * revolutions;
    const x = (R - r) * Math.cos(t) + d * Math.cos(((R - r) / r) * t);
    const y = (R - r) * Math.sin(t) - d * Math.sin(((R - r) / r) * t);
    const px = cx + scale * (x * cos - y * sin);
    const py = cy + scale * (x * sin + y * cos);
    path += `${i === 0 ? 'M' : 'L'}${px.toFixed(1)} ${py.toFixed(1)}`;
  }
  return `${path}Z`;
}

/** The rosette as paths: the same curve turned a little each time, like a guilloche engraving. */
export function roseSet(spec: CoverSpec, cx: number, cy: number, radius: number): string[] {
  const out: string[] = [];
  for (let i = 0; i < spec.copies; i += 1) {
    out.push(rosettePath(spec, cx, cy, radius, ((spec.rotation + (i * 360) / spec.copies) * Math.PI) / 180));
  }
  return out;
}

/** Up to two capital letters that stand for the deck's name, for the centre of the cover. */
export function monogram(name: string): string {
  const words = name
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 0 && !/^(the|of|and|in|for|a|an|to)$/i.test(w));
  if (words.length === 0) return 'S';
  const first = [...words[0]!][0]!.toUpperCase();
  const second = words.length > 1 ? [...words[1]!][0]!.toUpperCase() : '';
  return `${first}${second}`;
}

/**
 * The short title printed on a deck's cover. Long market names ("Trading Card
 * Games (TCG) / Collectible Card Games (CCG) Market") overrun a card-sized
 * cover, so the cover drops bracketed abbreviations, a trailing "Market", and
 * any alternative names after a slash. The full name stays in the text below.
 */
export function deckDisplayTitle(name: string): string {
  const full = name.replace(/\s+/g, ' ').trim();
  let short = full
    .replace(/\s*[([][^)\]]*[)\]]/g, '')
    .split(/\s+\/\s+/)[0]!
    .replace(/\s+markets?$/i, '')
    .replace(/^United States\b/, 'US')
    .replace(/\s+([,;:])/g, '$1')
    .replace(/[\s,;:\-–—]+$/, '')
    .trim();
  if (!short) short = full;
  return short;
}

/** Cover title size in px: smaller for longer titles, so three lines always fit. */
export function deckTitleSize(title: string): number {
  const n = title.length;
  if (n <= 20) return 17;
  if (n <= 34) return 15;
  if (n <= 48) return 13.5;
  return 12.5;
}
